do $test$
declare actor uuid:=gen_random_uuid();other uuid:=gen_random_uuid();org uuid:=gen_random_uuid();s uuid:=gen_random_uuid();t uuid:=gen_random_uuid();sp uuid:=gen_random_uuid();req uuid:=gen_random_uuid();r jsonb;r2 jsonb;d jsonb;pid uuid;mid uuid;z uuid;sid uuid;prior bigint;versions bigint;
begin
 insert into auth.users(id,email,email_confirmed_at,created_at,updated_at) select id,id||'@field-test.invalid',now(),now(),now() from unnest(array[actor,other]) id;
 insert into public.profiles(id,display_name) select id,'新品回滾測試' from unnest(array[actor,other]) id on conflict do nothing;
 insert into public.organizations(id,name,business_type,store_mode) values(org,'新品回滾測試','SINGLE_RESTAURANT','MULTI');
 insert into public.stores(id,organization_id,name,store_code,created_by) values(s,org,'BeApe','FP'||substr(s::text,1,8),actor),(t,org,'Gras','FP'||substr(t::text,1,8),actor);
 insert into public.organization_members(organization_id,user_id,role,is_owner,can_manage_business) values(org,actor,'STAFF',false,false),(org,other,'STAFF',false,false);
 insert into public.staff_identities(organization_id,user_id,display_name,created_by) select org,id,'新品測試',actor from unnest(array[actor,other]) id;
 insert into public.store_memberships(store_id,organization_id,user_id,login_identifier,role,work_role,assigned_by) values(s,org,actor,'field-test','STAFF','STAFF',actor);
 insert into public.suppliers(id,organization_id,supplier_code,name,is_active) values(sp,org,'TEST','測試廠商',true);
 perform set_config('request.jwt.claim.sub',actor::text,true);
 select count(*) into prior from private.stock_positions;
 select count(*) into versions from private.ingredient_standard_versions;
 d:=jsonb_build_object('name','回滾測試生蠔','unit','顆','supplier_id',sp,'unit_price',45);
 r:=public.create_field_product(s,s,d,req);pid:=(r->>'id')::uuid;mid:=(r->>'ingredient_id')::uuid;
 assert r->>'created'='true';assert public.create_field_product(s,s,d,req)=r,'retry duplicates';
 assert (select count(*)=1 from public.products where id=pid);
 assert (select current_supplier_id=sp from public.products where id=pid);
 assert (select cost_price=45 and review_status='pending' from private.ingredient_masters where id=mid);
 assert (select supplier_id=sp from private.ingredient_price_choices where ingredient_id=mid);
 assert (private.resolved_cost_quote(s,pid,'回滾測試生蠔','顆',current_date)->>'price')::numeric=45;
 assert private.resolved_cost_quote(s,pid,'回滾測試生蠔','箱',current_date)->>'price' is null,'unsafe package conversion';
 assert private.resolved_cost_quote(s,pid,'回滾測試生蠔','顆',current_date-1)->>'price' is null,'historical price rewrite';
 assert (select count(*)=prior from private.stock_positions),'stock mutated';
 assert not exists(select 1 from public.store_product_opening_balances where product_id=pid),'invented opening balance';
 assert exists(select 1 from public.zone_products zp join public.count_zones cz on cz.id=zp.zone_id where zp.product_id=pid and cz.store_id=s and cz.name='未分類');
 assert exists(select 1 from jsonb_array_elements(public.field_product_options(s,s)->'products') x where x->>'id'=pid::text);
 begin perform public.create_field_product(s,s,d||'{"unit_price":46}',req);raise exception 'conflict accepted';exception when sqlstate '23505' then null;end;
 r2:=public.create_field_product(s,s,jsonb_build_object('name','回滾測試生蠔','unit','顆'),gen_random_uuid());assert r2->>'id'=pid::text,'duplicate product';
 assert (select cost_price=45 from private.ingredient_masters where id=mid),'reuse overwrote price';
 r2:=public.create_field_product(s,s,'{"name":"無價測試","unit":"包"}',gen_random_uuid());
 assert (select cost_price is null from private.ingredient_masters where id=(r2->>'ingredient_id')::uuid),'missing price became zero';
 begin perform public.create_field_product(s,s,'{"name":"無單位"}',gen_random_uuid());raise exception 'missing unit accepted';exception when sqlstate '22023' then null;end;
 begin perform public.create_field_product(s,s,'{"name":"錯價","unit":"包","unit_price":-1}',gen_random_uuid());raise exception 'negative accepted';exception when sqlstate '22023' then null;end;
 begin perform public.create_field_product(s,s,jsonb_build_object('name','錯廠商','unit','包','supplier_id',gen_random_uuid()),gen_random_uuid());raise exception 'foreign supplier accepted';exception when sqlstate '22023' then null;end;
 update public.products set is_active=false where id=pid;
 begin perform public.create_field_product(s,s,'{"name":"回滾測試生蠔","unit":"顆"}',gen_random_uuid());raise exception 'disabled accepted';exception when sqlstate '22023' then null;end;
 assert not exists(select 1 from public.products where id=pid and is_active);update public.products set is_active=true where id=pid;
 insert into private.count_field_removed(store_id,product_id,removed_by) values(s,pid,actor);
 begin perform public.create_field_product(s,s,'{"name":"回滾測試生蠔","unit":"顆"}',gen_random_uuid());raise exception 'removed accepted';exception when sqlstate '22023' then null;end;
 delete from private.count_field_removed where store_id=s and product_id=pid;
 select zp.zone_id into z from public.zone_products zp where product_id=pid limit 1;
 insert into public.inventory_count_sessions(organization_id,store_id,started_by,status,snapshot,paper_required) values(org,s,actor,'IN_PROGRESS','{"zones":[]}',false) returning id into sid;
 d:=jsonb_build_object('name','盤點新品','unit','瓶','session_id',sid,'zone_id',z);
 r2:=public.create_field_product(s,s,d,gen_random_uuid());
 assert exists(select 1 from public.inventory_count_sessions cs cross join lateral jsonb_array_elements(cs.snapshot->'zones') x where cs.id=sid and x->>'product_id'=r2->>'id');
 assert (select quantity is null from private.count_opening_snapshots where session_id=sid and product_id=(r2->>'id')::uuid);
 insert into public.count_zone_progress(organization_id,session_id,zone_id,status) values(org,sid,z,'COMPLETED');
 begin perform public.create_field_product(s,s,d||'{"name":"不可新增"}',gen_random_uuid());raise exception 'completed accepted';exception when sqlstate '22023' then null;end;
 assert not exists(select 1 from public.products where organization_id=org and name='不可新增');
 update private.ingredient_masters set cost_price=50,review_status='confirmed',revision=revision+1 where id=mid;
 assert (private.resolved_cost_quote(s,pid,'回滾測試生蠔','顆',current_date)->>'price')::numeric=50,'confirmed price not preferred';
 update public.store_memberships set access_mode='VIEW' where store_id=s and user_id=actor;
 begin perform public.create_field_product(s,s,d,gen_random_uuid());raise exception 'view accepted';exception when sqlstate '42501' then null;end;
 update public.store_memberships set access_mode='EDIT' where store_id=s and user_id=actor;
 perform set_config('request.jwt.claim.sub',other::text,true);
 begin perform public.field_product_options(s,s);raise exception 'nonmember read accepted';exception when sqlstate '42501' then null;end;
 begin perform public.create_field_product(s,s,d,gen_random_uuid());raise exception 'nonmember accepted';exception when sqlstate '42501' then null;end;
 perform set_config('request.jwt.claim.sub','',true);
 begin perform public.create_field_product(s,s,d,gen_random_uuid());raise exception 'anon accepted';exception when sqlstate '42501' then null;end;
 perform set_config('request.jwt.claim.sub',actor::text,true);
 r2:=public.create_field_product(s,t,'{"name":"二店新品","unit":"包"}',gen_random_uuid());assert r2->>'store_id'=t::text;
 begin perform public.create_field_product(s,gen_random_uuid(),'{"name":"其他店","unit":"包"}',gen_random_uuid());raise exception 'unrelated store accepted';exception when sqlstate '42501' then null;end;
 assert not has_function_privilege('anon','public.create_field_product(uuid,uuid,jsonb,uuid)','EXECUTE');
end $test$;
